--
-- Name: clickup_settings; Type: TABLE; Schema: integrations; Owner: -
--

CREATE TABLE integrations.clickup_settings (
    id smallint DEFAULT 1 NOT NULL,
    onboarding_space_name text DEFAULT 'QMS Onboarding'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT clickup_settings_id_check CHECK ((id = 1)),
    CONSTRAINT clickup_settings_onboarding_space_name_check CHECK ((btrim(onboarding_space_name) <> ''::text))
);


--
-- Name: clickup_task_steps; Type: TABLE; Schema: integrations; Owner: -
--

CREATE TABLE integrations.clickup_task_steps (
    step_key text NOT NULL,
    label text NOT NULL,
    ordinal integer NOT NULL,
    phrases text[] NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT clickup_task_steps_label_check CHECK ((btrim(label) <> ''::text)),
    CONSTRAINT clickup_task_steps_ordinal_check CHECK ((ordinal >= 1)),
    CONSTRAINT clickup_task_steps_phrases_check CHECK ((cardinality(phrases) > 0))
);


--
-- Name: dropbox_configuration; Type: TABLE; Schema: integrations; Owner: -
--

CREATE TABLE integrations.dropbox_configuration (
    id smallint DEFAULT 1 NOT NULL,
    app_key text,
    app_secret_ciphertext bytea,
    refresh_token_ciphertext bytea,
    root_namespace_id text,
    root_path text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT dropbox_configuration_id_check CHECK ((id = 1))
);


--
-- Name: process_street_settings; Type: TABLE; Schema: integrations; Owner: -
--

CREATE TABLE integrations.process_street_settings (
    id smallint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    sync_interval_hours smallint DEFAULT 24 NOT NULL,
    api_key_ciphertext bytea,
    schedule_mode text DEFAULT 'interval'::text NOT NULL,
    sync_time time without time zone,
    sync_timezone text,
    CONSTRAINT process_street_settings_daily_time_requires_time_and_zone CHECK (((schedule_mode <> 'daily_time'::text) OR ((sync_time IS NOT NULL) AND (sync_timezone IS NOT NULL)))),
    CONSTRAINT process_street_settings_id_check CHECK ((id = 1)),
    CONSTRAINT process_street_settings_schedule_mode_check CHECK ((schedule_mode = ANY (ARRAY['interval'::text, 'daily_time'::text]))),
    CONSTRAINT process_street_settings_sync_interval_hours_check CHECK (((sync_interval_hours >= 1) AND (sync_interval_hours <= 168))),
    CONSTRAINT process_street_settings_sync_timezone_check CHECK (((sync_timezone IS NULL) OR (sync_timezone = ANY (ARRAY['America/Los_Angeles'::text, 'America/Denver'::text, 'America/Chicago'::text, 'America/New_York'::text, 'UTC'::text, 'Europe/Belgrade'::text]))))
);


--
-- Name: ps_task_role_name; Type: TABLE; Schema: integrations; Owner: -
--

CREATE TABLE integrations.ps_task_role_name (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    role text NOT NULL,
    task_name text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT ps_task_role_name_task_name_check CHECK ((btrim(task_name) <> ''::text))
);


--
-- Name: user_clickup_credentials; Type: TABLE; Schema: integrations; Owner: -
--

CREATE TABLE integrations.user_clickup_credentials (
    user_id uuid NOT NULL,
    token_ciphertext bytea NOT NULL,
    clickup_user_id text,
    clickup_username text,
    status text DEFAULT 'valid'::text NOT NULL,
    last_validated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_clickup_credentials_status_check CHECK ((status = ANY (ARRAY['valid'::text, 'invalid'::text])))
);


